function mg_followup_attachment():?string{global $d,$u;if(!ManagementMeetingsRepository::canFollowupDecision($d,$u))throw new DomainException('فقط مسئول یا ناظر مجاز به ثبت پیگیری است.');if(empty($_FILES['attachment']['name']))return null;$s=Upload::save($_FILES['attachment'],'uploads/management-followups',['pdf','doc','docx','xls','xlsx','jpg','jpeg','png','webp'],10*1024*1024);if(!$s['ok'])throw new InvalidArgumentException($s['error']);return json_encode(['original_name'=>$s['original_name'],'file_path'=>$s['file_path'],'mime_type'=>$s['mime_type'],'file_size'=>$s['file_size']],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);}
if($_SERVER['REQUEST_METHOD']==='POST'){try{if(!Auth::verifyCsrf($_POST['_csrf']??null))throw new DomainException('اعتبار فرم منقضی شده است.');$action=(string)($_POST['action']??'followup');if($action==='followup')ManagementMeetingsRepository::updateDecisionStatus($id,(string)($_POST['new_status']??''),(int)($_POST['progress_percent']??0),(string)($_POST['followup_note']??''),(int)$u['id'],trim((string)($_POST['next_followup_date']??''))?:null,mg_followup_attachment());elseif($action==='verify')ManagementMeetingsRepository::verifyDecision($id,(int)$u['id']);elseif($action==='update')ManagementMeetingsRepository::updateDecision($id,$_POST,(int)$u['id']);elseif($action==='convert_rule')ManagementMeetingsRepository::convertDecisionToRule($id,$_POST,(int)$u['id']);flash(['followup'=>'وضعیت پیگیری بروزرسانی شد.','verify'=>'انجام مصوبه تأیید شد.','update'=>'مصوبه بروزرسانی شد.','convert_rule'=>'قانون مصوب با موفقیت فعال شد.'][$action]??'عملیات انجام شد.');}catch(InvalidArgumentException|DomainException $e){flash($e->getMessage(),'danger');}catch(Throwable $e){error_log('Decision view: '.$e->getMessage());flash('انجام عملیات مصوبه ممکن نشد.','danger');}redirect('/admin/management-decision-view.php?id='.$id);}
